/**
 * The made-up people of Coach exam v2 (exam/v2/CASES.md), as Aven 2 records. Everything is generated by code from a
 * short spec with a fixed seed, so every run, model and judge sees exactly the same data.
 */
import type { NewRecord } from '../../src/engine/plan';
import type { ActivityType, MemoryCard } from '../../src/engine/model';

export const TZ = 'Europe/Copenhagen';
const DAY = 864e5;
export const at = (day: string, hh = 12, mm = 0) => Date.parse(`${day}T${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}:00${offset(day)}`);
/** Copenhagen is +02:00 until the last Sunday of October, +01:00 after */
const offset = (day: string) => (day >= '2026-10-25' || day < '2026-03-29' ? '+01:00' : '+02:00');
export const addDay = (day: string, n: number) => new Date(Date.parse(`${day}T12:00:00Z`) + n * DAY).toISOString().slice(0, 10);
const weekday = (day: string) => new Date(`${day}T12:00:00Z`).getUTCDay();

/** a small fixed-seed random, so "about 2,740 a day" is the same numbers on every run */
function rng(seed: string) {
  let h = 2166136261;
  for (const c of seed) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return () => { h = Math.imul(h ^ (h >>> 15), 2246822507); h = Math.imul(h ^ (h >>> 13), 3266489909); h ^= h >>> 16; return (h >>> 0) / 4294967296; };
}

export interface Lift { ex: string; kg: number; reps: number; /** kg added every `every` sessions (0 = stuck) */ step?: number; every?: number }
export interface PersonSpec {
  id: string;
  name?: string;
  lang: 'en' | 'da';
  targets?: { kcal?: number; protein?: number; carbs?: number; fat?: number; waterMl?: number };
  memory?: { text: string; topic: MemoryCard['topic']; from?: string; until?: string; goal?: MemoryCard['goal'] }[];
  /** weigh-ins: start kg on `from`, change per week, every n days, until the day before `to` */
  weights?: { from: string; to: string; kg: number; perWeek: number; every: number; noise?: number };
  /** food logs: one entry a day between from and to (exclusive), around kcal/protein; days where skip() is true have none */
  food?: { from: string; to: string; kcal: number; protein: number; spread?: number; complete?: boolean; skipEvery?: number; estimated?: boolean };
  /** food logged so far today */
  today?: { day: string; kcal: number; protein: number; hh?: number };
  water?: { day: string; ml: number }[];
  /** weekday (0 Sunday … 6 Saturday) → routine name, plus sport days */
  plan?: { weekly: Record<number, string>; sports?: Record<number, ActivityType[]>; cleared?: string[] };
  /** finished sessions: on these days, with these lifts progressing as given */
  sessions?: { days: string[]; name: (day: string, i: number) => string; lifts: (day: string, i: number) => Lift[] };
  activities?: { day: string; type: ActivityType; min: number; km?: number }[];
  sleep?: { endDay: string; hours: number }[];
}

/** Build a person's records. Ids are stable: `<person>:<kind>:<n>`. */
export function records(p: PersonSpec): NewRecord[] {
  const out: NewRecord[] = [];
  let n = 0;
  const id = (kind: string) => `${p.id}:${kind}:${n++}`;
  const r = rng(p.id);
  const push = (rec: Record<string, unknown>) => out.push(rec as unknown as NewRecord);

  push({ id: 'settings', kind: 'settings', language: p.lang, dayStartHour: 0, weekStart: 1, units: { weight: 'kg', distance: 'km', length: 'cm' }, restDefaultSec: 120, targets: p.targets ?? {}, ...(p.name ? { name: p.name } : {}), at: at('2026-09-01'), tz: TZ, day: '2026-09-01' });

  for (const m of p.memory ?? []) {
    const from = m.from ?? '2026-09-01';
    push({ id: id('memory'), kind: 'memory', text: m.text, topic: m.topic, scope: m.until ? 'oneOff' : 'standing', validFrom: from, ...(m.until ? { validUntil: m.until } : {}), lastSeen: at(from), origin: 'said', ...(m.goal ? { goal: m.goal } : {}), at: at(from), tz: TZ, day: from });
  }

  if (p.weights) {
    const w = p.weights;
    for (let d = w.from, i = 0; d < w.to; d = addDay(d, w.every), i += w.every) {
      const kg = Math.round((w.kg + (w.perWeek * i) / 7 + (r() - 0.5) * (w.noise ?? 0.4)) * 10) / 10;
      push({ id: id('bodyweight'), kind: 'bodyweight', kg, at: at(d, 7), tz: TZ, day: d });
    }
  }

  if (p.food) {
    const f = p.food;
    let i = 0;
    for (let d = f.from; d < f.to; d = addDay(d, 1), i++) {
      if (f.skipEvery && i % f.skipEvery !== 0) continue;
      const s = f.spread ?? 0.08;
      const kcal = Math.round(f.kcal * (1 + (r() - 0.5) * 2 * s));
      const protein = Math.round(f.protein * (1 + (r() - 0.5) * 2 * s));
      push({ id: id('food'), kind: 'food', name: 'Day of meals', meal: 'dinner', dataSource: f.estimated ? 'estimate' : 'reference', portion: { amount: 1, unit: 'portion' }, estimated: !!f.estimated, nutrients: { kcal, protein }, at: at(d, 19), tz: TZ, day: d });
      if (f.complete !== false) push({ id: `day:${p.id}:${d}`, kind: 'dayNote', foodComplete: true, at: at(d, 22), tz: TZ, day: d });
    }
  }
  if (p.today) push({ id: id('food'), kind: 'food', name: 'Meals so far', meal: 'lunch', dataSource: 'reference', portion: { amount: 1, unit: 'portion' }, estimated: false, nutrients: { kcal: p.today.kcal, protein: p.today.protein }, at: at(p.today.day, p.today.hh ?? 13), tz: TZ, day: p.today.day });
  for (const w of p.water ?? []) push({ id: id('water'), kind: 'water', ml: w.ml, at: at(w.day, 10), tz: TZ, day: w.day });

  if (p.plan) {
    const names = [...new Set(Object.values(p.plan.weekly))];
    const rid = new Map(names.map((name) => [name, `${p.id}:routine:${name.toLowerCase().replace(/\W+/g, '-')}`]));
    for (const [name, rId] of rid) push({ id: rId, kind: 'routine', name, items: [], at: at('2026-09-01'), tz: TZ, day: '2026-09-01' });
    const weekly = Object.fromEntries(Array.from({ length: 7 }, (_, wd) => [wd, p.plan!.weekly[wd] ? rid.get(p.plan!.weekly[wd])! : null]));
    push({ id: `${p.id}:plan`, kind: 'plan', mode: 'weekly', weekly, rotation: { order: [], pointer: 0, perWeek: 0 }, overrides: [], cleared: p.plan.cleared ?? [], activities: p.plan.sports ?? {}, at: at('2026-09-01'), tz: TZ, day: '2026-09-01' });
  }

  if (p.sessions) {
    p.sessions.days.forEach((day, i) => {
      const sid = id('session');
      push({ id: sid, kind: 'session', name: p.sessions!.name(day, i), state: 'finished', events: [], pausedMs: 0, startedAt: at(day, 17), endedAt: at(day, 18), at: at(day, 17), tz: TZ, day });
      p.sessions!.lifts(day, i).forEach((l, k) => {
        const slot = id('slot');
        push({ id: slot, kind: 'slot', sessionId: sid, exerciseId: l.ex, order: k, at: at(day, 17), tz: TZ, day });
        for (let s = 0; s < 3; s++) push({ id: id('set'), kind: 'set', sessionId: sid, slotId: slot, order: s, type: 'working', done: { kg: l.kg, reps: Math.max(1, l.reps - (s === 2 ? 1 : 0)), at: at(day, 17, 5 + s * 3) }, at: at(day, 17), tz: TZ, day });
      });
    });
  }
  for (const a of p.activities ?? []) push({ id: id('activity'), kind: 'activity', type: a.type, durationSec: a.min * 60, ...(a.km ? { distanceM: a.km * 1000 } : {}), startAt: at(a.day, 18), at: at(a.day, 18), tz: TZ, day: a.day });
  for (const s of p.sleep ?? []) push({ id: id('sleep'), kind: 'sleep', start: at(s.endDay, 7) - s.hours * 36e5, end: at(s.endDay, 7), at: at(s.endDay, 7), tz: TZ, day: s.endDay });
  return out;
}

/** the training days between two dates that fall on the given weekdays */
export function daysOn(from: string, to: string, weekdays: number[], skip: string[] = []): string[] {
  const out: string[] = [];
  for (let d = from; d < to; d = addDay(d, 1)) if (weekdays.includes(weekday(d)) && !skip.includes(d)) out.push(d);
  return out;
}

/** a lift that climbs `step` kg every `every` sessions, from its start */
export const climb = (ex: string, kg: number, reps: number, step: number, every: number, i: number): Lift => ({ ex, kg: kg + step * Math.floor(i / every), reps });
